// QuorumCert is an auto generated low-level Go binding around an user-defined struct.
type QuorumCert struct {
	Epoch       uint64
	ViewNumber  uint64
	BlockHash   common.Hash
	BlockNumber uint64
	BlockIndex  uint32
	ExtendHash  common.Hash
}

var (
	RateABI  = "[{\"type\":\"constructor\",\"inputs\":[{\"name\":\"_electionAddr\",\"type\":\"address\",\"internalType\":\"address\"},{\"name\":\"_decimals\",\"type\":\"uint8\",\"internalType\":\"uint8\"}],\"stateMutability\":\"nonpayable\"},{\"type\":\"function\",\"name\":\"blockNumber\",\"inputs\":[],\"outputs\":[{\"name\":\"\",\"type\":\"uint256\",\"internalType\":\"uint256\"}],\"stateMutability\":\"view\"},{\"type\":\"function\",\"name\":\"decimals\",\"inputs\":[],\"outputs\":[{\"name\":\"\",\"type\":\"uint8\",\"internalType\":\"uint8\"}],\"stateMutability\":\"view\"},{\"type\":\"function\",\"name\":\"rate\",\"inputs\":[],\"outputs\":[{\"name\":\"\",\"type\":\"uint256\",\"internalType\":\"uint256\"}],\"stateMutability\":\"view\"},{\"type\":\"function\",\"name\":\"update\",\"inputs\":[{\"name\":\"newRate\",\"type\":\"uint256\",\"internalType\":\"uint256\"},{\"name\":\"qc\",\"type\":\"tuple\",\"internalType\":\"structQuorumCert\",\"components\":[{\"name\":\"epoch\",\"type\":\"uint64\",\"internalType\":\"uint64\"},{\"name\":\"viewNumber\",\"type\":\"uint64\",\"internalType\":\"uint64\"},{\"name\":\"blockHash\",\"type\":\"bytes32\",\"internalType\":\"bytes32\"},{\"name\":\"blockNumber\",\"type\":\"uint64\",\"internalType\":\"uint64\"},{\"name\":\"blockIndex\",\"type\":\"uint32\",\"internalType\":\"uint32\"},{\"name\":\"extendHash\",\"type\":\"bytes32\",\"internalType\":\"bytes32\"}]},{\"name\":\"bitmap\",\"type\":\"bytes\",\"internalType\":\"bytes\"},{\"name\":\"signature\",\"type\":\"bytes\",\"internalType\":\"bytes\"},{\"name\":\"leafIndex\",\"type\":\"uint256\",\"internalType\":\"uint256\"},{\"name\":\"proof\",\"type\":\"bytes32[]\",\"internalType\":\"bytes32[]\"}],\"outputs\":[],\"stateMutability\":\"nonpayable\"},{\"type\":\"event\",\"name\":\"UpdateRate\",\"inputs\":[{\"name\":\"blockNumber\",\"type\":\"uint256\",\"indexed\":false,\"internalType\":\"uint256\"},{\"name\":\"rate\",\"type\":\"uint256\",\"indexed\":false,\"internalType\":\"uint256\"}],\"anonymous\":false}]"
	RateCode = ""
)

type RateGenesisCaller struct {
	evmFunc func(address common.Address) *vm.EVM
	abi     *abi.ABI
	to      common.Address
	caller  common.Address
}

func NewRateGenesisCaller(ctx sdk.Context, db sdk.StateDB, chainConfig *params.ChainConfig) (*RateGenesisCaller, error) {
	abi, err := abi.JSON(strings.NewReader(RateABI))
	if err != nil {
		return nil, err
	}
	return &RateGenesisCaller{
		evmFunc: func(address common.Address) *vm.EVM {
			return vm2.NewEVM(vm2.NewGenesisBlockContext(), address, db, chainConfig, nil)
		},
		abi: &abi,
	}, nil
}

func (c *RateGenesisCaller) DeployRate(_electionAddr common.Address, _decimals uint8) error {

	var data []byte
	var err error

	data, err = c.abi.Constructor.Inputs.Pack(_electionAddr, _decimals)
	if err != nil {
		return err
	}

	evm := c.evmFunc(c.caller)
	_, _, _, err = evm.CreateAppContract(vm.AccountRef(c.caller), append(common.FromHex(RateCode), data...), c.to, math.MaxUint64, big.NewInt(0))
	return err
}

func (c *RateGenesisCaller) PackBlockNumber() ([]byte, error) {
	input, err := c.abi.Pack("blockNumber")
	if err != nil {
		return nil, err
	}
	return input, nil
}
func (c *RateGenesisCaller) BlockNumber() (*big.Int, error) {
	evm := c.evmFunc(c.caller)

	var err error
	var input []byte
	var output []byte
	input, err = c.PackBlockNumber()
	if err != nil {
		return *new(*big.Int), err
	}
	output, _, err = evm.Call(vm.AccountRef(c.caller), c.to, input, math.MaxUint64, big.NewInt(0))
	if err != nil {
		return *new(*big.Int), err
	}

	out, err := c.abi.Unpack("blockNumber", output)
	if err != nil {
		return *new(*big.Int), err
	}

	out0 := *abi.ConvertType(out[0], new(*big.Int)).(**big.Int)

	return out0, err
}

func (c *RateGenesisCaller) PackDecimals() ([]byte, error) {
	input, err := c.abi.Pack("decimals")
	if err != nil {
		return nil, err
	}
	return input, nil
}
