func (c *RateGenesisCaller) PackUpdate(newRate *big.Int, qc QuorumCert, bitmap []byte, signature []byte, leafIndex *big.Int, proof []common.Hash) ([]byte, error) {
	input, err := c.abi.Pack("update", newRate, qc, bitmap, signature, leafIndex, proof)
	if err != nil {
		return nil, err
	}
	return input, nil
}
func (c *RateGenesisCaller) Update(newRate *big.Int, qc QuorumCert, bitmap []byte, signature []byte, leafIndex *big.Int, proof []common.Hash) error {
	evm := c.evmFunc(c.caller)

	var err error
	var input []byte

	input, err = c.PackUpdate(newRate, qc, bitmap, signature, leafIndex, proof)
	if err != nil {
		return err
	}

	_, _, err = evm.Call(vm.AccountRef(c.caller), c.to, input, math.MaxUint64, big.NewInt(0))

	return err
}

func (c *RateGenesisCaller) ABI() *abi.ABI {
	return c.abi
}
